import numpy as np


def softmax(x, axis=-1):
    e = np.exp(x - np.max(x, axis=axis, keepdims=True))
    return e / e.sum(axis=axis, keepdims=True)


def scaled_dot_product_attention(Q, K, V, mask=None):
    d_k = K.shape[-1]
    scores = Q @ K.T / np.sqrt(d_k)
    if mask is not None:
        scores = np.where(mask, scores, -1e9)
    weights = softmax(scores, axis=-1)
    return weights @ V, weights


def self_attention(X, Wq, Wk, Wv):
    return scaled_dot_product_attention(X @ Wq, X @ Wk, X @ Wv)


words = ["the", "cat", "sat", "on", "the", "mat"]
rng = np.random.default_rng(0)
X = rng.standard_normal((6, 4))                        # one 4-d embedding per word
Wq, Wk, Wv = (rng.standard_normal((4, 4)) * 0.5 for _ in range(3))
result = self_attention(X, Wq, Wk, Wv)
if result is None:
    print("self_attention() returned None")
else:
    out, weights = result
    print("output shape:", out.shape, "weights shape:", weights.shape)
    print(np.round(weights, 2))
    for i, word in enumerate(words):
        print(f"{word:>4} attends most to '{words[int(np.argmax(weights[i]))]}'")
